abstract class Shape { abstract double area(); }       // абстракция
class Circle extends Shape {                            // наследование
  private final double r;                               // инкапсуляция (private)
  Circle(double r) { this.r = r; }
  double area() { return Math.PI * r * r; }              // полиморфизм (переопределение)
}
class Square extends Shape {
  private final double a;
  Square(double a) { this.a = a; }
  double area() { return a * a; }
}
// единообразная работа через абстракцию:
List<Shape> shapes = List.of(new Circle(2), new Square(3));
double total = shapes.stream().mapToDouble(Shape::area).sum();
