// Race condition
class Counter {
    private int count = 0;
    public void increment() { count++; }  // НЕ атомарно: чтение+1+запись
    public int get() { return count; }
}
// 1000 потоков, каждый increment() 1000 раз → ожидаем 1 000 000,
// получаем ~950 000 (потерянные обновления).

// Решение 1: synchronized
class SafeCounter {
    private int count = 0;
    public synchronized void increment() { count++; }
}

// Решение 2: AtomicInteger (CAS, без блокировок)
class AtomicCounter {
    private AtomicInteger count = new AtomicInteger(0);
    public void increment() { count.incrementAndGet(); }
}

// Check-then-act race
if (!map.containsKey(k)) {  // другой поток может добавить между проверкой и put
    map.put(k, v);
}
// Решение: ConcurrentHashMap.putIfAbsent(k, v)
