class User {
    private int id;
    private String name;

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (o == null || getClass() != o.getClass()) return false;
        User user = (User) o;
        return id == user.id && Objects.equals(name, user.name);
    }

    @Override
    public int hashCode() {
        return Objects.hash(id, name);  // те же поля, что в equals
    }
}

// Без переопределения:
Set<User> set = new HashSet<>();
set.add(new User(1, "A"));
set.add(new User(1, "A"));  // разные ссылки → set.size() == 2 (баг!)

// С переопределением:
// set.size() == 1 (равные по equals, одинаковый hashCode)

// Record (Java 16) — автоматически
class User(int id, String name) {}
// equals и hashCode по всем полям автоматически

// Lombok
@EqualsAndHashCode
class User { private int id; private String name; }
