    @Transactional
    public void createOrder(OrderRequest req) {
        Order order = orderRepo.save(new Order(req));  // основное изменение
        outboxRepo.save(new OutboxEvent(
            order.getId(), "OrderCreated", toJson(order)));  // событие в той же транзакции
    }  // commit — обе записи атомарно
}

// Poller
@Component
class OutboxPoller {
    @Scheduled(fixedDelay = 1000)
    public void publish() {
        List<OutboxEvent> events = outboxRepo.findPending();
        for (OutboxEvent e : events) {
            kafkaTemplate.send("orders", e.getAggregateId(), e.getPayload());
            e.setStatus("SENT");
        }
        outboxRepo.saveAll(events);
    }
}

// CDC (Debezium) — читает WAL, публикует без polling:
// debezium connector для outbox таблицы → Kafka topic
// real-time, без нагрузки polling'ом
